Action: run_sql({'query': "\nWITH crit AS (\n  SELECT i.slchd_establishment_key, i.inspection_id, i.inspection_date,\n         EXTRACT(year FROM i.inspection_date) AS yr,\n         COUNT(*) FILTER (WHERE vc.critical) AS crit_count\n  FROM inspections i\n  LEFT JOIN violations v ON v.inspection_id = i.inspection_id\n  LEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id\n  WHERE i.inspection_date >= DATE '2021-07-17'\n  GROUP BY i.slchd_establishment_key, i.inspection_id, i.inspection_date\n),\nyearly AS (\n  SELECT slchd_establishment_key, yr, SUM(crit_count) AS crit_sum, COUNT(*) AS n_insp\n  FROM crit\n  GROUP BY slchd_establishment_key, yr\n),\nstats AS (\n  SELECT slchd_establishment_key,\n         COUNT(DISTINCT yr) AS n_years,\n         regr_slope(crit_sum, yr) AS slope,\n         MIN(yr) AS first_yr, MAX(yr) AS last_yr\n  FROM yearly\n  GROUP BY slchd_establishment_key\n  HAVING COUNT(DISTINCT yr) >= 2\n)\nSELECT ek.name, ek.address, ek.city, s.n_years, s.slope, s.first_yr, s.last_yr\nFROM stats s\nJOIN establishment_keys ek ON ek.slchd_establishment_key = s.slchd_establishment_key\nORDER BY s.slope DESC\nLIMIT 15\n"})

