Action: plot_chart({'query': "\nWITH crit AS (\n  SELECT i.slchd_establishment_key, i.inspection_id,\n         EXTRACT(year FROM i.inspection_date) AS yr,\n         COUNT(*) FILTER (WHERE vc.critical) AS crit_count\n  FROM inspections i\n  LEFT JOIN violations v ON v.inspection_id = i.inspection_id\n  LEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id\n  WHERE i.inspection_date >= DATE '2021-07-17'\n  GROUP BY i.slchd_establishment_key, i.inspection_id, EXTRACT(year FROM i.inspection_date)\n),\nyearly AS (\n  SELECT slchd_establishment_key, yr, SUM(crit_count) AS crit_sum\n  FROM crit GROUP BY slchd_establishment_key, yr\n),\nstats AS (\n  SELECT slchd_establishment_key, regr_slope(crit_sum, yr) AS slope, COUNT(DISTINCT yr) AS n_years\n  FROM yearly GROUP BY slchd_establishment_key HAVING COUNT(DISTINCT yr) >= 2\n)\nSELECT ek.name || ' (' || ek.city || ')' AS restaurant, s.slope\nFROM stats s JOIN establishment_keys ek ON ek.slchd_establishment_key = s.slchd_establishment_key\nORDER BY s.slope DESC LIMIT 10\n", 'chart_type': 'bar', 'x': 'restaurant', 'y': 'slope', 'title': 'Top 10 restaurants with rising critical-violation trend (last 5 yrs)'})

